from models import upgrade
from storage import load_all, save


def test_v1_to_v2_name_becomes_title():
    v1 = {"id": 1, "name": "Alice", "remote": "yes"}
    result = upgrade(v1)
    assert result == {"id": 1, "title": "Alice", "work_mode": "remote", "version": 2}, f"Got {result}"
    # input must not be modified
    assert v1 == {"id": 1, "name": "Alice", "remote": "yes"}, f"Input was modified: {v1}"


def test_v1_name_becomes_title_office():
    v1 = {"id": 2, "name": "Bob", "remote": "no"}
    result = upgrade(v1)
    assert result == {"id": 2, "title": "Bob", "work_mode": "office", "version": 2}, f"Got {result}"


def test_v1_missing_remote_unknown():
    v1 = {"id": 3, "name": "Carol"}
    result = upgrade(v1)
    assert result == {"id": 3, "title": "Carol", "work_mode": "unknown", "version": 2}, f"Got {result}"


def test_v1_invalid_remote_raises_valueerror():
    v1 = {"id": 4, "name": "Dave", "remote": "maybe"}
    try:
        upgrade(v1)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_v2_record_returned_as_equal_copy():
    v2 = {"version": 2, "id": 5, "title": "Eve", "work_mode": "office"}
    result = upgrade(v2)
    assert result == v2, f"Got {result}, expected {v2}"
    # input must not be modified
    assert v2 == {"version": 2, "id": 5, "title": "Eve", "work_mode": "office"}


def test_v2_idempotent():
    v2 = {"version": 2, "id": 6, "title": "Frank", "work_mode": "remote"}
    result = upgrade(upgrade(v2))
    assert result == v2


def test_load_all_returns_v2_for_mixed_input():
    rows = [
        {"id": 1, "name": "Alice", "remote": "yes"},
        {"version": 2, "id": 2, "title": "Bob", "work_mode": "office"},
        {"id": 3, "name": "Carol"},
    ]
    result = load_all(rows)
    assert all(r.get("version") == 2 for r in result), f"Not all v2: {result}"
